 * Parsing of the election input.
 *
 * The grammar is line based: `candidates <name>...` exactly once before any
 * `ballot <count> <candidate>...` line. Blank lines and `#` comments are
 * ignored. Every failure is reported as a ParseError carrying the exact
 * message the command must print.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/

export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ParseError'
  }
}

function fail(line, message) {
  throw new ParseError(`line ${line}: ${message}`)
}

/** Split the raw input into lines, dropping the empty tail a trailing newline leaves. */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function parseCandidates(words, lineNo, state) {
  if (state.candidates !== null) {
    fail(lineNo, 'candidates must be declared once, before any ballot')
  }
  const names = words.slice(1)
  if (names.length === 0) fail(lineNo, 'expected candidates <name>...')
  const seen = new Set()
  for (const name of names) {
    if (!NAME_RE.test(name)) fail(lineNo, `invalid candidate name ${name}`)
    if (seen.has(name)) fail(lineNo, `candidate ${name} is declared twice`)
    seen.add(name)
  }
  state.candidates = names
  state.declared = seen
}

function parseBallot(words, lineNo, state) {
  if (state.candidates === null) {
    fail(lineNo, 'candidates must be declared once, before any ballot')
  }
  if (words.length < 3) fail(lineNo, 'expected ballot <count> <candidate>...')
  const rawCount = words[1]
  if (!/^[1-9][0-9]*$/.test(rawCount)) {
    fail(lineNo, 'count must be a positive integer')
  }
  const count = Number(rawCount)
  const ranking = words.slice(2)
  const seen = new Set()
  for (const name of ranking) {
    if (!state.declared.has(name)) fail(lineNo, `unknown candidate ${name}`)
    if (seen.has(name)) fail(lineNo, `candidate ${name} is repeated`)
    seen.add(name)
  }
  state.ballots.push({ count, ranking })
}

/**
 * Parse an election, returning `{ candidates, ballots }` where each ballot is
 * `{ count, ranking }`. Throws ParseError on the first problem found.
 */
export function parseElection(input) {
  const state = { candidates: null, declared: null, ballots: [] }
  const lines = splitLines(input)

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const text = lines[i].trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/)

