    else if (words[0] === 'ballot') parseBallot(words, lineNo, state)
    else fail(lineNo, `unknown directive ${words[0]}`)
  }

  if (state.candidates === null) throw new ParseError('no candidates')
  return { candidates: state.candidates, ballots: state.ballots }
}
"}

