{"file_path":"src/count.js","content":"/**
 * The instant-runoff count.
 *
 * Each round every ballot counts for the first candidate on it that is still
 * continuing; ballots with no continuing choice left are exhausted. A majority
 * of the active total wins; otherwise the weakest candidate is eliminated and
 * another round is counted.
 */

/** Order names by descending vote count, then by ascending name. */
export function orderNames(names, counts) {
  return [...names].sort((a, b) => {
    const diff = counts.get(b) - counts.get(a)
    if (diff !== 0) return diff
    return a < b ? -1 : a > b ? 1 : 0
  })
}

/**
 * Choose which of the tied candidates to eliminate: compare their counts over
 * the rounds counted so far, keeping the fewest at the first round that
 * separates them, and falling back to the name sorting last by code point.
 */
function breakTie(tied, history) {
  let survivors = [...tied]
  let separated = true

  while (survivors.length > 1 && separated) {
    separated = false
    for (const round of history) {
      const values = survivors.map((name) => round.get(name))
      const min = Math.min(...values)
      const max = Math.max(...values)
      if (min === max) continue
      survivors = survivors.filter((name) => round.get(name) === min)
      separated = true
      break
    }
  }

  if (survivors.length === 1) return survivors[0]
  return survivors.reduce((worst, name) => (name > worst ? name : worst))
}

/** Count one round over the continuing candidates. */
function countRound(ballots, continuing) {
  const counts = new Map()
  for (const name of continuing) counts.set(name, 0)
  let exhausted = 0

  for (const ballot of ballots) {
    const choice = ballot.ranking.find((name) => counts.has(name))
    if (choice === undefined) exhausted += ballot.count
    else counts.set(choice, counts.get(choice) + ballot.count)
  }

  return { counts, exhausted }
}

/**
 * Run the election. Returns `{ rounds, winner }` where each round is
 * `{ counts, exhausted, order, eliminated }` and `winner` is null when no
 * candidate ever reached a majority.
 */
export function runElection(election) {
  let continuing = [...election.candidates]
  const rounds = []
  const history = []

  for (;;) {
    const { counts, exhausted } = countRound(election.ballots, continuing)
    history.push(counts)
    const order = orderNames(continuing, counts)
    const round = { counts, exhausted, order, eliminated: null }
    rounds.push(round)

    let active = 0
    for (const name of continuing) active += counts.get(name)

    if (active === 0) return { rounds, winner: null }

    const leader = order[0]
    if (counts.get(leader) * 2 > active) return { rounds, winner: leader }

    const fewest = Math.min(...continuing.map((name) => counts.get(name)))
    const tied = continuing.filter((name) => counts.get(name) === fewest)
    const out = tied.length === 1 ? tied[0] : breakTie(tied, history)
    round.eliminated = out
    continuing = continuing.filter((name) => name !== out)
  }
}
"}

