/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parseElection } from './parse.js'
import { runElection } from './count.js'

const MODES = new Set(['rounds', 'tally'])

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function report(mode, result) {
  const lines = []

  if (mode === 'rounds') {
